import{_ as t,o as a,c as n,a4 as p}from"./chunks/framework.hWlsC8BY.js";const f=JSON.parse('{"title":"最低收购价收购守的是底线2026-09-24","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"最低收购价收购守的是底线2026-09-24","date":"2026-09-24T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"http://ipaper.ce.cn/pc/content/202609/24/content_339367.html","summary":"第05版：\\n时评\\n上一版\\n下一版\\n标题导航\\n更好发挥财政政策集成效应\\n最低收购价收购守的是底线\\n闲置校舍变养老院一举两得\\n“几秒打扰”莫成常态\\n摒弃AI“拿来主义”\\n立足县域激活历史经典产业\\n来稿邮箱\\n上一篇\\n下一篇\\n2026-09-24\\n放大+\\n缩小-\\n默认\\no\\n最低收购价收购守的是底线\\n...\\n","contentHash":"5f73c95a60d89e20bd9c74e03388cddc","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-09-24-最低收购价收购守的是底线.md","filePath":"policies/2026-09-24-最低收购价收购守的是底线.md"}'),l={name:"policies/2026-09-24-最低收购价收购守的是底线.md"};function r(i,e,o,c,_,s){return a(),n("div",null,[...e[0]||(e[0]=[p('<h1 id="最低收购价收购守的是底线2026-09-24" tabindex="-1">最低收购价收购守的是底线2026-09-24 <a class="header-anchor" href="#最低收购价收购守的是底线2026-09-24" aria-label="Permalink to &quot;最低收购价收购守的是底线2026-09-24&quot;">​</a></h1><blockquote><p>来源: <a href="http://ipaper.ce.cn/pc/content/202609/24/content_339367.html" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-09-24 摘要: 第05版： 时评 上一版 下一版 标题导航 更好发挥财政政策集成效应 最低收购价收购守的是底线 闲置校舍变养老院一举两得 “几秒打扰”莫成常态 摒弃AI“拿来主义” 立足县域激活历史经典产业 来稿邮箱 上一篇 下一篇 2026-09-24 放大+ 缩小- 默认 o 最低收购价收购守的是底线 ...</p></blockquote><ul><li>更好发挥财政政策集成效应</li><li>最低收购价收购守的是底线</li><li>闲置校舍变养老院一举两得</li><li>“几秒打扰”莫成常态</li><li>摒弃AI“拿来主义”</li><li>立足县域激活历史经典产业</li><li>来稿邮箱</li></ul><p>更好发挥财政政策集成效应</p><p>最低收购价收购守的是底线</p><p>闲置校舍变养老院一举两得</p><p>“几秒打扰”莫成常态</p><p>摒弃AI“拿来主义”</p><p>立足县域激活历史经典产业</p><p>来稿邮箱</p><h2 id="最低收购价收购守的是底线" tabindex="-1">最低收购价收购守的是底线 <a class="header-anchor" href="#最低收购价收购守的是底线" aria-label="Permalink to &quot;最低收购价收购守的是底线&quot;">​</a></h2><p>最低收购价收购守的是底线</p><p>最低收购价收购并非让农民躺平也能赚钱，而是让广大农民可以安心种粮，把更多精力投向提质增效，把种粮的功夫真正用在品质和市场竞争力上。托市是市场的补充而非替代，是补位而非越位。它守的是底线，放的是活力。</p><p>眼下，秋粮收购大幕已开启。国家粮食和物资储备局有关负责人在国新办9月21日举行的“开局起步‘十五五’”系列主题新闻发布会上明确提到，最低收购价收购是组织好粮食大规模收购的重要路径之一。然而，每逢提及最低收购价收购，总有一种声音将其简单化、标签化，认为最低收购价收购就是躺平式收购，国家包收包揽，企业躺平经营，农民“躺着”卖粮。这种理解偏离了最低收购价政策的本质。</p><p>最低收购价收购并非躺平式收购，从启动与退出机制便可见一斑。执行预案有严格启动条件，只有当主产区粮食收购价连续3天低于国家公布的最低收购价时，才能按规定程序启动，且并非全省所有地区同时启动；当市场价回升至最低收购价以上时，及时退出，把空间交还市场。今年受供强需弱影响，粮价弱势运行，部分主产区跌破最低收购价，若放任不管，农民将面临“丰产不丰收”。夏粮收购期间，有关部门及时在江西、湖南启动早籼稻以及在河南、安徽启动稻谷最低收购价收购。截至9月中旬，已收购最低收购价小麦120万吨、早籼稻90万吨。占比虽低，却起到“四两拨千斤”作用，既支撑市场，又守住农民“种粮卖得出”的底线。</p><p>作为最低收购价收购的执行主体，中储粮也没有躺平。每到收购旺季，中储粮提前研判市场、科学测算仓容，统筹设立库点、调配人员设备、备足收购资金，确保敞开收购、应收尽收。一旦在主产区启动最低收购价收购，中储粮就会及时公布库点、挂牌敞开收购，开展前置检验、优化售粮服务，推广预约收购、错峰售粮，做到“人等粮、钱等粮、仓等粮”。严把入库、储存、出库“三道关”。收购时并非来者不拒，粮食必须符合国家标准三等以上质量要求；储存期间定期组织抽检，动态掌握质量状况，发现异常及时处置，防止品质劣变；出库时必检，坚决防止不符合食品安全标准的粮食流入口粮市场和食品生产企业。</p><p>最低收购价收购并非让农民躺平也能赚钱。如果农民躺着就能卖上高价，谁还愿意费心选良种、精耕细作？如果好粮次粮一个价，谁还有动力琢磨市场需要什么粮？最低收购价收购“保底不封顶”，为粮食市场化收购留出溢价空间。有了最低收购价收购托底，广大农民可以安心种粮，把更多精力投向提质增效，把种粮的功夫真正用在品质和市场竞争力上。他们改变“种什么卖什么”的传统习惯，紧盯市场“要什么种什么”，主动调优品种结构，扩大优质专用小麦、优质稻谷种植面积；他们不再满足于“种得出”，而是追求“种得好”，在测土配方施肥、绿色防控、精细田管上下足功夫，努力让好粮卖上好价。</p><p>最低收购价收购，对监管的要求极高。自我国实施最低收购价收购以来，“人情粮”“转圈粮”等痼疾便如影随形、屡禁不止。有的收购点人为压级压价，把好粮当次粮收，克扣农民应得的价款；有的抬级抬价，把次粮当好粮收，套取国家补贴。更有甚者，搞虚购虚销、以陈顶新、低收高转，玩起“转圈粮”的把戏，把国家的最低收购价收购资金装进自家腰包。这些行为看似隐蔽，实则侵蚀的是最低收购价政策的公信力，蚕食的是农民的获得感。如果监管跟着躺平，最低收购价收购就会从“惠农”异化为“坑农”，把“保底”扭曲成“套利”，政策初衷势必落空。正因如此，监管绝对不能躺平。要加大监管力度，持续推进“铁拳行动”，用好12325监管热线，对坑农害农行为发现一起严查一起，绝不姑息。</p><p>组织好大规模粮食收购，需要统筹做好市场化收购和政策性收储。托市是市场的补充而非替代，是补位而非越位。它守的是底线，放的是活力。托市不躺平，市场有活力，农民得实惠，这正是我国粮食收购市场平稳运行的关键所在。</p><p><a href="http://ipaper.ce.cn/pc/content/202609/24/content_339367.html" target="_blank" rel="noreferrer">阅读原文</a></p>',20)])])}const h=t(l,[["render",r]]);export{f as __pageData,h as default};
